CREATE TABLE "municipality" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar(200) UNIQUE NOT NULL
);

CREATE TABLE "discipline" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar(200) UNIQUE NOT NULL,
    "updated_at" timestamptz,
    "created_at" timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE "rank" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar(100) UNIQUE NOT NULL,
    "ttl" varchar(50),
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz
);

CREATE TABLE "judge_category" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "competition_type" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar(100) UNIQUE NOT NULL,
    "updated_at" timestamptz,
    "created_at" timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE "competition_level" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "code" varchar(30),
    "name" varchar(100),
    "updated_at" timestamptz,
    "created_at" timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE "calendar_plan" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar(200) NOT NULL,
    "year" smallint NOT NULL
);

CREATE TABLE "age_group" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar(100) UNIQUE NOT NULL,
    "min_age" smallint,
    "max_age" smallint
);

CREATE TABLE "judge_position" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar(100) UNIQUE NOT NULL
);

COMMENT ON TABLE "judge_position" IS 'Предложенная структура: на скриншоте поля справочника ещё не определены.';
COMMENT ON COLUMN "judge_position"."name" IS 'Например: главный судья, главный секретарь, судья';
